                    if (oldListeners.mouseenter) {
                        buttonContainer.removeEventListener('mouseenter', oldListeners.mouseenter);
                    }
                    if (oldListeners.mouseleave) {
                        buttonContainer.removeEventListener('mouseleave', oldListeners.mouseleave);
                    }
